    const idle=()=>!root.dataset.paused&&!hover&&performance.now()>userUntil;
    const btn = root.querySelector('.btn');
    let busy = false;
    const go = async () => {
      if (busy) return;
      busy = true;
      btn.dataset.s = 'load';
      await wait(1700);
      btn.dataset.s = 'done';
      await wait(1700);
      btn.dataset.s = 'idle';
      await wait(700);
      busy = false;
    };
    btn.addEventListener('click', () => { touch(); go(); });
    (async () => {
      await wait(500);
      while (root.isConnected) {
        if (idle()) await go();
        await wait(1200);
